// Prépare la liste des pages à interroger sur l'API Recherche d'entreprises (data.gouv)
const cfg = $('Config').first().json;
const sd = $getWorkflowStaticData('global');
const manuel = $execution.mode !== 'production';
const modeTest = cfg.MODE_TEST === true || String(cfg.MODE_TEST).toLowerCase() === 'true' || manuel;
const nb = Math.max(1, Math.min(20, Number(cfg.PAGES_PAR_RUN) || 6));
const debut = modeTest ? 1 : (Number(sd.page) || 1);
const out = [];
for (let p = debut; p < debut + nb && p <= 400; p++) {
  out.push({ json: { page: p, page_debut: debut, nb_pages: nb, mode_test: modeTest, execution_manuelle: manuel } });
}
return out;

// Garde les grandes entreprises dont le siège est en Île-de-France et choisit leur dirigeant (PDG)
const cfg = $('Config').first().json;
const prep = $('Préparer la recherche').first().json;
const sd = $getWorkflowStaticData('global');
sd.vus = sd.vus || {};
const modeTest = prep.mode_test;
const attente = sd.attente || {};                      // adresses valides déjà trouvées mais pas encore envoyées
const nbAttente = modeTest ? 0 : Object.keys(attente).length;

// Solde de crédits Scalelist (appel gratuit) : on ne lance jamais plus de recherches qu'il ne reste de crédits
function lireCredits(o) {
  const vals = [];
  (function voir(x, chemin) {
    if (x === null || x === undefined) return;
    if (typeof x === 'object') { for (const k of Object.keys(x)) voir(x[k], chemin ? chemin + '.' + k : k); return; }
    if (typeof x === 'number' && /credit/i.test(chemin)) vals.push({ chemin, v: x });
  })(o, '');
  if (vals.length === 1) return vals[0].v;
  const pref = vals.filter(e => /remain|balance|available|left|restant/i.test(e.chemin));
  if (pref.length === 1) return pref[0].v;
  return null; // format non reconnu : pas de limite appliquée
}
let credits = null;
try { const cr = $('Scalelist – Solde de crédits').first().json; if (cr && !cr.error) credits = lireCredits(cr); } catch (e) { credits = null; }
const IDF = ['75', '77', '78', '91', '92', '93', '94', '95'];
// Secteurs visés (sections NAF). Vide = tous les secteurs.
const SECTEURS = String(cfg.SECTEURS_NAF || '').toUpperCase().split(/[^A-Z]+/).filter(Boolean);
// Activités exclues : débuts de code NAF (ex. 65 = assurance, 64.1 = banques, 96.03 = services funéraires)
const NAF_EXCLUS = String(cfg.EXCLURE_NAF || '').split(/[,;\s]+/).map(x => x.trim()).filter(Boolean);
// Entreprises exclues : mots contenus dans le nom (ex. VEOLIA)
const sansAccent = x => String(x || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase();
const NOMS_EXCLUS = String(cfg.EXCLURE_NOMS || '').split(/[,;]+/).map(x => sansAccent(x).trim()).filter(Boolean);

const norm = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[’`]/g, "'").toLowerCase().replace(/\s+/g, ' ').trim();
function rang(qualite) {
  const q = norm(qualite);
  if (!q) return null;
  if (/administrateur|commissaire|membre|vice|delegue|suppleant|autre|controleur|liquidateur|adjoint|representant|censeur|secretaire/.test(q)) {
    if (!/president.*directeur general/.test(q)) return null;
  }
  if (/president.*directeur general|president-directeur general|^pdg$/.test(q)) return 1;
  if (/^president du conseil d'administration/.test(q)) return 2;
  if (/^president/.test(q) && !/surveillance/.test(q) && !/directoire/.test(q)) return 3;
  if (/^president du directoire/.test(q)) return 4;
  if (/^directeur general/.test(q)) return 5;
  if (/^gerant/.test(q)) return 6;
  return null;
}
const PARTICULES = ['de', 'du', 'des', 'la', 'le', 'les', 'dit', 'd', 'l', 'von', 'van', 'der', 'den', 'da', 'di', 'del', 'el', 'al', 'ben'];
function casse(s, particules) {
  return String(s || '').toLowerCase().split(/(\s+|-|')/).map((m, i) => {
    if (!m || /^(\s+|-|')$/.test(m)) return m;
    if (particules && i > 0 && PARTICULES.includes(m)) return m;
    return m.charAt(0).toUpperCase() + m.slice(1);
  }).join('').replace(/\s+/g, ' ').trim();
}
function adresseSiege(s) {
  const voie = [s.numero_voie, s.indice_repetition, s.type_voie, s.libelle_voie].filter(Boolean).join(' ');
  return casse(voie, true);
}

const vus = new Set();
const candidats = [];
let totalResultats = 0;
function traiterPage(res) {
  totalResultats += res.length;
  for (const r of res) {
    if (!r || !r.siren || vus.has(r.siren)) continue;
    vus.add(r.siren);
    const siege = r.siege || {};
    if (r.etat_administratif && r.etat_administratif !== 'A') continue;
    if (!IDF.includes(String(siege.departement || ''))) continue;          // siège social en Île-de-France
    if (String(r.categorie_entreprise || '') !== String(cfg.CATEGORIE || 'GE')) continue; // grande entreprise
    if (!String(r.nature_juridique || '').startsWith('5')) continue;       // sociétés commerciales uniquement
    if (SECTEURS.length && !SECTEURS.includes(String(r.section_activite_principale || '').toUpperCase())) continue; // secteur non visé
    const codeNaf = String(r.activite_principale || '');
    if (NAF_EXCLUS.some(p => codeNaf.startsWith(p))) continue;             // activité exclue (banque, assurance...)
    const nomTest = sansAccent((r.nom_raison_sociale || '') + ' ' + (r.nom_complet || ''));
    if (NOMS_EXCLUS.some(m => nomTest.includes(m))) continue;              // entreprise exclue par son nom
    if (!modeTest && (sd.vus[r.siren] || attente[r.siren])) continue;     // déjà traitée lors d'une exécution précédente
    let best = null;
    for (const d of (r.dirigeants || [])) {
      if (d.type_dirigeant !== 'personne physique' || !d.nom || !d.prenoms) continue;
      const k = rang(d.qualite);
      if (k === null) continue;
      if (!best || k < best.k) best = { k, d };
    }
    if (!best) continue;
    const brut = String(best.d.nom);
    const m = brut.match(/^(.*?)\s*\((.*?)\)\s*$/);
    const nom = casse(m ? m[1] : brut, true);
    const nomAlt = m ? casse(m[2], true) : '';
    const prenom = casse(String(best.d.prenoms).split(/[\s,]+/)[0], false);
    const entreprise = String(r.nom_raison_sociale || r.nom_complet || '').replace(/\s+/g, ' ').trim();
    if (!entreprise || !nom || !prenom) continue;
    candidats.push({
      siren: r.siren,
      entreprise,
      sigle: r.sigle || '',
      section: r.section_activite_principale || '',
      naf: r.activite_principale || '',
      adresse_ligne: adresseSiege(siege),
      code_postal: siege.code_postal || '',
      ville: siege.libelle_commune || '',
      departement: siege.departement || '',
      dirigeant_prenom: prenom,
      dirigeant_nom: nom,
      dirigeant_nom_alt: nomAlt,
      dirigeant_qualite: String(best.d.qualite || '').replace(/’/g, "'"),
    });
  }
}
// Chaque exécution prend EXACTEMENT N nouvelles entreprises (N = CANDIDATURES_PAR_JOUR, 1 crédit Scalelist chacune).
// Si les pages déjà reçues ne suffisent pas, on lit les pages suivantes de data.gouv jusqu'à en avoir N.
const helpers = this.helpers;
const sleep = ms => new Promise(ok => setTimeout(ok, ms));
async function lirePage(p) {
  for (let essai = 0; essai < 3; essai++) {
    try {
      return await helpers.httpRequest({ method: 'GET', url: 'https://recherche-entreprises.api.gouv.fr/search', qs: { categorie_entreprise: cfg.CATEGORIE || 'GE', region: '11', etat_administratif: 'A', per_page: 25, page: p }, json: true, timeout: 30000 });
    } catch (e) { await sleep(2000 * (essai + 1)); }
  }
  return null;
}
const objectif = modeTest ? (Number(cfg.MAX_TEST) || 2) : (Number(cfg.CANDIDATURES_PAR_JOUR) || 10);
let plafond = objectif;
if (credits !== null) plafond = Math.max(0, Math.min(plafond, Math.floor(credits)));
const recues = $input.all().map(it => (it.json && it.json.results) || []);
let prochaine = prep.page_debut;
let lues = 0;
for (let p = prep.page_debut; candidats.length < plafond && p <= 400 && lues < 80; p++, lues++) {
  let res = recues[p - prep.page_debut];
  if (!res) { const rep = await lirePage(p); if (!rep) break; res = rep.results || []; await sleep(300); }
  if (!res.length) { prochaine = 1; break; }            // fin de la liste : on repartira du début (les déjà-vues sont ignorées)
  traiterPage(res);
  prochaine = candidats.length > plafond ? p : p + 1;   // page pas entièrement utilisée : on y revient demain
}
if (!modeTest) { sd.page = prochaine; sd.maj = Date.now(); }
const lot = candidats.slice(0, plafond);
const commun = { mode_test: modeTest, objectif, en_attente: nbAttente, credits_scalelist: credits, dernier_lot: false, page_debut: prep.page_debut, nb_pages: prep.nb_pages };
if (lot.length === 0) {
  return nbAttente > 0 ? [{ json: { factice: true, ...commun } }] : [];
}
return lot.map(c => ({ json: { ...c, ...commun } }));

// Boucle : lit la réponse de Scalelist pour UNE entreprise. E-mail trouvé ? vérifié (Valid) ? domaine cohérent ?
// Compte les e-mails valides et signale l'arrêt dès que l'objectif du jour est atteint.
const cfg = $('Config').first().json;
const sd = $getWorkflowStaticData('global');
sd.vus = sd.vus || {};
const c = $('Une entreprise à la fois').first().json;   // entreprise du passage en cours
const r = ($input.first() && $input.first().json) || {};
const accepterRisky = cfg.ACCEPTER_EMAILS_RISKY === true || String(cfg.ACCEPTER_EMAILS_RISKY).toLowerCase() === 'true';
const RE_MAIL = /^[A-Za-z0-9._%+'-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$/;

function explorer(obj, visite, chemin) {
  if (obj === null || obj === undefined) return;
  if (typeof obj !== 'object') { visite(chemin, obj); return; }
  for (const k of Object.keys(obj)) {
    if (k === 'custom') continue; // nos propres données renvoyées en écho
    explorer(obj[k], visite, chemin ? chemin + '.' + k : k);
  }
}
function lire(r) {
  let email = '', statutBrut = '';
  explorer(r, (chemin, v) => {
    if (typeof v !== 'string') return;
    const cle = chemin.split('.').pop().toLowerCase();
    if (!email && RE_MAIL.test(v.trim()) && /mail/.test(cle)) email = v.trim();
    if (!statutBrut && /status|statut|result|verif|quality|state/.test(cle) && /valid|risky|catch|not[ _-]?found|unknown/i.test(v)) statutBrut = v.trim();
  });
  if (!email) explorer(r, (chemin, v) => { if (!email && typeof v === 'string' && RE_MAIL.test(v.trim())) email = v.trim(); });
  return { email, statutBrut };
}

// Garde-fou : le domaine de l'adresse trouvée doit correspondre au nom de l'entreprise
// (Scalelist déduit le domaine du nom ; il peut se tromper de société).
const GENERIQUES = new Set(['france', 'francaise', 'francais', 'groupe', 'group', 'holding', 'societe', 'compagnie', 'international', 'internationale', 'europe', 'paris', 'services', 'service', 'national', 'nationale', 'generale', 'general', 'gestion', 'participations', 'financiere', 'industries', 'industrie', 'distribution', 'solutions']);
const plat = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
function domaineCoherent(email, c) {
  const dom = plat(String(email).split('@')[1] || '');
  const labels = dom.split('.').filter(Boolean);
  if (labels.length < 2) return false;
  const coeur = labels.slice(0, -1).join('').replace(/[^a-z0-9]/g, '');
  const mots = plat(c.entreprise).split(/[^a-z0-9]+/).filter(Boolean);
  const colle = mots.join('');
  const sigle = plat(c.sigle).replace(/[^a-z0-9]/g, '');
  const acronyme = mots.map(m => m[0]).join('');
  if (mots.some((m, i) => !GENERIQUES.has(m) && (m.length >= 4 || (i === 0 && m.length >= 3)) && coeur.includes(m))) return true;
  if (sigle.length >= 3 && coeur.includes(sigle)) return true;
  if (acronyme.length >= 3 && coeur.includes(acronyme)) return true;
  if (coeur.length >= 4 && colle.includes(coeur)) return true;
  return false;
}

if (r.custom && r.custom.siren && String(r.custom.siren) !== String(c.siren)) {
  throw new Error(`Incohérence : la réponse Scalelist (SIREN ${r.custom.siren}) ne correspond pas à l'entreprise en cours (${c.entreprise}, ${c.siren}). Arrêt par sécurité.`);
}
const moi = $('E-mail trouvé et vérifié ?');
const dejaRetenus = moi.isExecuted ? (Number(moi.last().json.total_retenus) || 0) : (Number(c.en_attente) || 0);
const modeTest = c.mode_test;
const erreur = r.error ? (typeof r.error === 'string' ? r.error : JSON.stringify(r.error)) : '';
const creditsEpuises = !!erreur && /402|credit/i.test(erreur);
if (erreur && !creditsEpuises && /401|unauthor|api key/i.test(erreur)) {
  throw new Error('Scalelist a refusé la requête (clé API invalide) : ' + erreur.slice(0, 300));
}
const { email, statutBrut } = erreur ? { email: '', statutBrut: '' } : lire(r);
let statut = 'non_trouve';
if (creditsEpuises) statut = 'credits_epuises';
else if (erreur) statut = 'erreur';
else if (email && /risky|catch/i.test(statutBrut)) statut = 'risky';
else if (email && /valid/i.test(statutBrut) && !/invalid/i.test(statutBrut)) statut = 'valid';
else if (email) statut = 'inconnu';
if (email && !domaineCoherent(email, c)) statut = 'domaine_douteux';
// Anti-doublon par ADRESSE : un même dirigeant peut diriger plusieurs filiales (SIREN différents, même e-mail)
const emailsDeja = new Set([...Object.values(sd.vus || {}).map(v => v && v.email), ...Object.values(sd.attente || {}).map(a => a && a.email_pdg)].filter(Boolean).map(x => String(x).toLowerCase()));
if (!modeTest && email && emailsDeja.has(email.toLowerCase())) statut = 'deja_contacte';
const ok = statut === 'valid' || (statut === 'risky' && accepterRisky);
if (!modeTest && statut !== 'erreur' && statut !== 'credits_epuises') {
  sd.vus[c.siren] = { statut: ok ? 'email_trouve' : statut, date: new Date().toISOString().slice(0, 10), entreprise: c.entreprise, email };
}
// En réel : seules les adresses trouvées, vérifiées et cohérentes sont retenues. En test : tout est retenu pour contrôle.
const retenu = creditsEpuises ? false : (modeTest ? true : ok);
const total = dejaRetenus + (retenu ? 1 : 0);
const fiche = {
  ...c,
  email_pdg: email,
  email_statut: statut,
  email_statut_brut: statutBrut,
  scalelist_reponse: JSON.stringify(r).slice(0, 600),
  destinataire: modeTest ? cfg.EMAIL_TEST : email,
  recherche_faite: !creditsEpuises,
  retenu,
  total_retenus: total,
  credits_epuises: creditsEpuises,
  stop: creditsEpuises, // on ne s'arrête plus aux e-mails valides : les N entreprises sont toutes recherchées
};
if (!modeTest && retenu) {
  // File d'attente : l'adresse est payée, elle sera envoyée même si une étape suivante tombe en panne aujourd'hui
  sd.seq = (Number(sd.seq) || 0) + 1;
  fiche.file_seq = sd.seq;                              // ordre d'arrivée dans la file
  sd.attente = { ...(sd.attente || {}), [c.siren]: fiche };
}
sd.maj = Date.now();
return [{ json: fiche }];

// Fin de boucle : candidatures à envoyer aujourd'hui = adresses valides en attente (anciennes d'abord) + nouvelles
const sd = $getWorkflowStaticData('global');
const tous = $input.all().map(i => i.json);
const reels = tous.filter(j => j.factice !== true);
const faits = reels.filter(j => j.recherche_faite === true);
const premier = tous[0] || {};
const modeTest = premier.mode_test !== false;
const objectif = Number(premier.objectif) || 10;
if (!modeTest && reels.length > 0 && premier.dernier_lot && faits.length === reels.length) {
  sd.page = premier.page_debut + premier.nb_pages; // toutes les entreprises de ces pages ont été traitées : pages suivantes demain
  sd.maj = Date.now();
}
const credits = tous.some(j => j.credits_epuises === true);
const aEnvoyer = modeTest ? faits.filter(j => j.retenu === true) : Object.values(sd.attente || {}).sort((a, b) => (a.file_seq || 0) - (b.file_seq || 0));
return aEnvoyer.map(j => ({ json: { ...j, mode_test: modeTest, objectif, nb_recherches: faits.length, nb_retenus: aEnvoyer.length, alerte_credits: credits, credits_scalelist: premier.credits_scalelist } }));

// Rédige le CV, la lettre de motivation et le mail personnalisés pour chaque entreprise
// ===== Bibliothèque de rédaction (CV, lettre, e-mail) — partagée par le node « Rédaction CV + lettre » =====
const MOI = {
  prenom: 'Adam', nom: 'SOUFANE', tel: '+33 7 45 45 05 95', email: 'adamsouf2006@gmail.com',
  ville: 'Creil', portfolio: 'https://portfolioadamsoufane.netlify.app/',
  linkedin: 'https://www.linkedin.com/in/adam-soufane-72aaa2366/',
};

// Secteur d'activité (section NAF) -> libellé + phrase d'accroche reliée à une expérience réelle
const SECTEURS = {
  A: ["de l'agriculture", "Le suivi des productions et des rendements repose sur des données nombreuses et hétérogènes : c'est précisément le type de données que j'ai appris à nettoyer, structurer et restituer."],
  B: ["des industries extractives", "Chez Veolia, j'ai travaillé sur des données reliant activités industrielles et substances émises : je suis à l'aise avec des référentiels techniques exigeants."],
  C: ["de l'industrie", "Chez Veolia, 76,8 % des données que j'ai traitées concernaient l'industrie manufacturière : je suis à l'aise avec les nomenclatures d'activités et les référentiels techniques propres au monde industriel."],
  D: ["de l'énergie", "L'énergie est un domaine que j'ai déjà abordé par les données : j'ai modélisé et prévu des séries de consommation en MWh (décomposition, ARIMA, Holt-Winters) et comparé les modèles par leurs erreurs de prévision (RMSE, MAE)."],
  E: ["de l'eau, des déchets et de l'environnement", "Mon stage chez Veolia m'a plongé dans les données de l'eau et de l'environnement : qualité des effluents, substances polluantes, exigences réglementaires. C'est un secteur dans lequel je souhaite continuer à progresser."],
  F: ["de la construction", "Le pilotage de chantiers et d'activités multi-sites demande des indicateurs fiables : j'ai conçu des tableaux de bord (Power BI, Looker Studio) reposant sur des modèles de données en étoile, pensés pour la décision."],
  G: ["du commerce et de la distribution", "J'ai mené un projet complet d'analyse décisionnelle des ventes sous Power BI : chiffre d'affaires, taux de transformation des devis, marge brute et analyse géographique, à partir d'un entrepôt de données modélisé en étoile."],
  H: ["du transport et de la logistique", "Les flux, les délais et les volumes du transport génèrent des séries de données que j'ai appris à analyser et à prévoir (séries temporelles, ARIMA), puis à restituer dans des tableaux de bord lisibles par les équipes opérationnelles."],
  I: ["de l'hôtellerie et de la restauration", "Une activité répartie sur de très nombreux sites se pilote par des indicateurs comparables d'un site à l'autre : j'ai conçu des tableaux de bord (Power BI, Looker Studio) reposant sur des modèles de données en étoile, pensés pour ce type de suivi."],
  J: ["du numérique et des médias", "Python, SQL et automatisation sont mon quotidien : chez Veolia, j'ai conçu une chaîne de huit scripts Python interrogeant une API externe, avec gestion des quotas et reprise sur interruption."],
  K: ["de la banque et de l'assurance", "La banque et l'assurance reposent sur la statistique et la qualité des données : ma formation (tests statistiques, échantillonnage, séries temporelles, classification) et mon expérience du dédoublonnage de données à grande échelle y trouvent une application directe."],
  L: ["de l'immobilier", "La gestion d'un patrimoine immobilier s'appuie sur des indicateurs fiables et actualisés : j'ai conçu des tableaux de bord (Power BI, Looker Studio) reposant sur des modèles de données en étoile, pensés pour la décision."],
  M: ["du conseil et des services aux entreprises", "Chez Veolia, j'ai appris à traduire un besoin métier en traitements de données documentés et réutilisables, puis à restituer les résultats à des experts non techniciens : une posture proche de celle du conseil."],
  N: ["des services aux entreprises", "Le pilotage d'activités de services demande des indicateurs fiables et partagés : j'ai conçu des tableaux de bord (Power BI, Looker Studio) reposant sur des modèles de données en étoile, pensés pour la décision."],
  O: ["des services publics", "Chez Veolia, j'ai travaillé sur des données au service des collectivités (eau municipale) et sur les nomenclatures officielles de l'INSEE : je connais les exigences de fiabilité et de traçabilité de ce type de données."],
  P: ["de l'enseignement et de la formation", "J'ai conduit une enquête statistique de bout en bout auprès d'étudiants (questionnaire, tests, restitution) : je sais transformer des réponses brutes en résultats clairs et exploitables."],
  Q: ["de la santé", "La santé est un domaine que j'ai abordé par la statistique : j'ai étudié et simulé en R des méthodes de randomisation pour les essais cliniques, afin de mesurer les déséquilibres entre groupes de patients."],
  R: ["de la culture et des loisirs", "J'ai mené une étude statistique sur les pratiques culturelles numériques des étudiants, du questionnaire à la restitution : un sujet qui rejoint directement votre activité."],
  T: ["des services à la personne", "Le pilotage d'activités de services demande des indicateurs fiables et partagés : j'ai conçu des tableaux de bord (Power BI, Looker Studio) reposant sur des modèles de données en étoile, pensés pour la décision."],
  U: ["des organisations internationales", "Chez Veolia, j'ai travaillé sur des nomenclatures officielles et des données réglementaires : je connais les exigences de fiabilité et de traçabilité de ce type de données."],
  S: ["des services", "Le pilotage d'activités de services demande des indicateurs fiables et partagés : j'ai conçu des tableaux de bord (Power BI, Looker Studio) reposant sur des modèles de données en étoile, pensés pour la décision."],
};
const SECTEUR_DEFAUT = ["", "Nettoyage, structuration, analyse statistique et restitution dans des tableaux de bord : ce sont les compétences que j'ai mises en pratique chez Veolia et que je souhaite mettre au service de vos équipes."];

function esc(s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
function secteur(section) { return SECTEURS[String(section || '').toUpperCase()] || SECTEUR_DEFAUT; }
function dateFr(d) {
  return new Intl.DateTimeFormat('fr-FR', { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'Europe/Paris' }).format(d || new Date());
}
function slug(s) {
